from lib import *
S = SS('x31')
steps = [
    step("默认规则与 rollbackFor / noRollbackFor(每个方法先 insert 一行,表里剩 1 行 = 提交,0 行 = 回滚)。抛 RuntimeException:回滚。抛 Error(AssertionError):回滚。抛受检异常 IOException(默认):提交——表里剩 1 行,事务没有回滚。rollbackFor = Exception.class、rollbackFor = IOException.class、rollbackForClassName = \"java.io.IOException\":都回滚。抛 RuntimeException 但声明了 noRollbackFor:提交。默认只有运行时异常和 Error 触发回滚,受检异常要自己用 rollbackFor 声明。", t=tl(S(1)), mark=lidx(S(1), '抛受检异常 IOException(默认)', '抛 RuntimeException,noRollbackFor'), done=lidx(S(1), '抛 RuntimeException  ', '抛 Error(AssertionError)', 'rollbackFor = Exception.class', 'rollbackFor = IOException.class', 'rollbackForClassName'), b=bars([['抛 RuntimeException:剩余行数', 0, '0(回滚)'], ['抛 Error:剩余行数', 0, '0(回滚)'], ['抛受检异常(默认):剩余行数', 1, '1(提交)'], ['抛受检异常 + rollbackFor:剩余行数', 0, '0(回滚)'], ['RuntimeException + noRollbackFor:剩余行数', 1, '1(提交)']], 1, done=[0, 1, 3], mark=[2, 4]), kv=KV([['默认回滚', 'RuntimeException 与 Error'], ['默认不回滚', '受检异常(提交!)'], ['rollbackFor', '声明哪些异常也回滚'], ['noRollbackFor', '声明哪些运行时异常不回滚']], ['默认不回滚'])),
    step("异常被包装或被吞掉。受检异常被包成 RuntimeException 再抛:调用者看到 RuntimeException ← IOException,回滚。方法内部 catch 把异常吞掉:调用者看到方法正常返回,表里剩 1 行,提交——事务拦截器根本不知道出过异常。吞掉异常但调用 TransactionAspectSupport.currentTransactionStatus().setRollbackOnly():方法正常返回,表里 0 行,回滚。事务只看方法有没有抛出异常,吞掉的异常要手动标记 rollback-only。", t=tl(S(2)), mark=lidx(S(2), '方法内部 catch 吞掉异常'), done=lidx(S(2), '受检异常包成 RuntimeException', 'setRollbackOnly()'), b=bars([['包成 RuntimeException 再抛:剩余行数', 0, '0(回滚)'], ['catch 吞掉异常:剩余行数', 1, '1(提交)'], ['吞掉并 setRollbackOnly():剩余行数', 0, '0(回滚)']], 1, done=[0, 2], mark=[1]), kv=KV([['包装成 RuntimeException', '会回滚'], ['catch 吞掉', '会提交,事务不知道出过错'], ['setRollbackOnly()', '手动要求回滚'], ['原则', '事务只看方法是否抛出异常']], ['catch 吞掉'])),
    step("rollbackFor 与 noRollbackFor 同时匹配时听谁的(MyChild 继承 MyChecked)。只写 rollbackFor = MyChecked,抛 MyChild:回滚(子类也匹配)。rollbackFor = MyChecked、noRollbackFor = MyChild,抛 MyChild:提交(noRollbackFor 的 MyChild 更近,听它的)。rollbackFor = MyChild、noRollbackFor = MyChecked,抛 MyChild:回滚(rollbackFor 的 MyChild 更近)。rollbackFor = RuntimeException、noRollbackFor = MyRuntime,抛 MyRuntime:提交。两边都匹配时,继承层次上离抛出的异常更近的那条规则赢。", t=tl(S(3)), mark=lidx(S(3), 'noRollbackFor = MyChild,抛 MyChild', 'noRollbackFor = MyRuntime,抛 MyRuntime'), done=lidx(S(3), '抛 MyChild(rollbackFor = MyChecked.class)', 'rollbackFor = MyChild,noRollbackFor = MyChecked,抛 MyChild'), b=bars([['只有 rollbackFor(父类):剩余行数', 0, '0(回滚)'], ['rollbackFor(父)+ noRollbackFor(子):剩余行数', 1, '1(提交)'], ['rollbackFor(子)+ noRollbackFor(父):剩余行数', 0, '0(回滚)'], ['rollbackFor(RuntimeException)+ noRollbackFor(MyRuntime):剩余行数', 1, '1(提交)']], 1, done=[0, 2], mark=[1, 3]), kv=KV([['两边都匹配', '继承上更近的那条赢'], ['子类 noRollbackFor 对父类 rollbackFor', '提交'], ['子类 rollbackFor 对父类 noRollbackFor', '回滚'], ['建议', '尽量不要同时写互相重叠的规则']], ['两边都匹配'])),
]
A = mkartx('x31', 31, 'Spring,事务,回滚,rollbackFor,受检异常,真实验证,动画演示',
    '实测事务回滚规则:RuntimeException 与 Error 回滚,受检异常 IOException 默认提交(表里剩 1 行);rollbackFor 才会回滚;方法内部吞掉异常就提交,setRollbackOnly() 可以手动回滚;rollbackFor 与 noRollbackFor 同时匹配时继承层次上更近的一条赢。',
    '@Transactional 抛了异常就一定回滚吗?受检异常呢?异常被 catch 吞掉呢?rollbackFor 和 noRollbackFor 同时命中谁说了算?这篇在 Spring Framework 7.0.9 和 MySQL 26.7.0 上逐个量出来。',
    [('提交', '抛受检异常 IOException 且没有写 rollbackFor 时的结果(表里剩 1 行)'), ('提交', '方法内部 catch 吞掉异常时的结果(事务不知道出过错)'), ('更近的赢', 'rollbackFor 与 noRollbackFor 同时匹配时继承层次上更近的那条规则决定')],
    [('默认规则', '<p>RuntimeException 与 Error 回滚,受检异常提交;rollbackFor 声明受检异常也回滚。</p>'),
     ('包装与吞掉', '<p>包成 RuntimeException 会回滚,catch 吞掉会提交,setRollbackOnly() 手动回滚。</p>'),
     ('规则冲突', '<p>两条规则都匹配时,继承层次上更近的一条赢。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 的 @EnableTransactionManagement + DataSourceTransactionManager + 自己起的 MySQL 26.7.0(innodb);“更近的赢”是根据四个例子的结果下的结论,没有读源码',
     '没有验证:@Transactional 放在类上与方法上的合并规则;提交本身失败(例如延迟的约束检查)时的行为;JTA;rollbackFor 与自定义 TransactionAttribute 的组合;Spring 的 DefaultTransactionAttribute 与 RuleBasedTransactionAttribute 内部细节'],
    '事务的回滚规则')
